[CmdletBinding()]param([string]$RepoRoot='.',[string]$OutputRoot='',[switch]$Force)
$ErrorActionPreference='Stop';$Root=(Resolve-Path $RepoRoot).Path;if([string]::IsNullOrWhiteSpace($OutputRoot)){$OutputRoot=Join-Path $Root '.artifacts\release-kit\1.2.8\context-handoff'};New-Item -ItemType Directory -Force $OutputRoot|Out-Null;$Stage=Join-Path ([IO.Path]::GetTempPath()) ('context-handoff-1.2.8-'+[guid]::NewGuid().ToString('N'));$Pack=Join-Path $Stage 'agentic-context-handoff-1.2.8';New-Item -ItemType Directory -Force $Pack|Out-Null;try{Copy-Item (Join-Path $Root 'integrations\companion-handoff-1.2.8\Update-AgenticContextHandoff-v1.2.8.ps1') $Pack;[IO.File]::WriteAllText((Join-Path $Pack 'VERSION.json'),([ordered]@{schema_version='1.0.0';ecosystem_version='1.2.8';component='context_handoff';version='1.2.8'}|ConvertTo-Json),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $Pack 'README.md'),'# Agentic Context Handoff 1.2.8`n`nAdds Action Packet and progress authority files to context exports.`n',[Text.UTF8Encoding]::new($false));$MF=Get-ChildItem $Pack -File|Sort-Object Name|%{[ordered]@{path=$_.Name;size_bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}};[IO.File]::WriteAllText((Join-Path $Pack 'MANIFEST.json'),([ordered]@{schema_version='1.0.0';ecosystem_version='1.2.8';files=@($MF)}|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$Zip=Join-Path $OutputRoot 'agentic-context-handoff-1.2.8.zip';Compress-Archive -Path (Join-Path $Pack '*') -DestinationPath $Zip -Force;Write-Host "Context Handoff package built: $Zip"}finally{Remove-Item $Stage -Recurse -Force -ErrorAction SilentlyContinue}
